package org.apache.commons.csv;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.StringReader;
import java.util.Map;

import org.apache.commons.lang3.StringUtils;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

public class CSVRecordTest_testToMap {

    private static final String MISSING_HEADER = "fourth";

    private enum EnumHeader {
        FIRST, SECOND, THIRD
    }

    private Map<String, Integer> headerMap;

    private CSVRecord record;

    private CSVRecord recordWithHeader;

    private String[] values;

    @BeforeEach
    public void setUp() throws Exception {
        values = new String[] { "A", "B", "C" };
        final String rowData = StringUtils.join(values, ',');
        try (CSVParser parser = CSVFormat.DEFAULT.parse(new StringReader(rowData))) {
            record = parser.iterator().next();
        }
        try (CSVParser parser = CSVFormat.DEFAULT.builder().setHeader(EnumHeader.class).get().parse(new StringReader(rowData))) {
            recordWithHeader = parser.iterator().next();
            headerMap = parser.getHeaderMap();
        }
    }

    private void assertHeaderValue(final Map<String, String> map, final EnumHeader header, final String expectedValue) {
        assertTrue(map.containsKey(header.name()));
        assertEquals(expectedValue, map.get(header.name()));
    }

    private void assertMissingHeaders(final Map<String, String> map, final boolean checkNullHeader) {
        assertFalse(map.containsKey(MISSING_HEADER));
        if (checkNullHeader) {
            assertFalse(map.containsKey(null));
        }
        assertNull(map.get(MISSING_HEADER));
    }

    private void validateMap(final Map<String, String> map, final boolean checkNullHeader) {
        assertHeaderValue(map, EnumHeader.FIRST, "A");
        assertHeaderValue(map, EnumHeader.SECOND, "B");
        assertHeaderValue(map, EnumHeader.THIRD, "C");
        assertMissingHeaders(map, checkNullHeader);
    }

    @Test
    void testToMap() {
        final Map<String, String> map = this.recordWithHeader.toMap();
        validateMap(map, true);
    }
}
